// Ambient type declarations for the lucide-react icon-data modules imported by
// lucideIcons.ts. Each icon module exports `__iconNode` (the raw SVG node data
// lucide uses to render the icon) alongside the React component.
declare module "lucide-react/dist/esm/icons/search.mjs" {
  export const __iconNode: ReadonlyArray<
    readonly [string, Readonly<Record<string, string | number>>]
  >;
}

